'use client'

import { forwardRef, useEffect, useState, useRef, useCallback, type ReactNode } from 'react'
import { motion, useSpring, useMotionValue, useReducedMotion } from 'motion/react'
import { cn } from '@/lib/utils'
import { playHoverSound, playClickSound } from '@/lib/sound'

interface Section {
  id: string
  title: ReactNode
  level: number
}

interface ScrollIndicatorProps {
  sections: Section[]
  activeIndex?: number
  onIndexChange?: (index: number) => void
  scrollRef?: React.RefObject<HTMLDivElement | null>
  scrollOffset?: number
  className?: string
}

export const ScrollIndicator = forwardRef<HTMLDivElement, ScrollIndicatorProps>(
  function ScrollIndicatorComponent(
    {
      sections,
      activeIndex: controlledIndex,
      onIndexChange,
      scrollRef: externalScrollRef,
      scrollOffset = 16,
      className,
    },
    ref,
  ) {
    const [internalIndex, setInternalIndex] = useState(0)
    const [isHovered, setIsHovered] = useState(false)
    const [trackHeight, setTrackHeight] = useState(0)
    const trackRef = useRef<HTMLDivElement>(null)
    const reduceMotion = useReducedMotion()

    const activeIndex = controlledIndex ?? internalIndex

    const progressY = useMotionValue(0)
    const smoothY = useSpring(progressY, {
      stiffness: reduceMotion ? 1000 : 300,
      damping: reduceMotion ? 100 : 30,
    })

    const filteredSections = sections.filter((s) => s.level === 2 || s.level === 3)
    const totalTicks = 60
    const lastTick = totalTicks - 1
    const tickY = (tick: number) => (tick / lastTick) * trackHeight
    const sectionTick = (index: number) =>
      Math.round((index / Math.max(filteredSections.length - 1, 1)) * lastTick)
    const activeTick = sectionTick(activeIndex)

    const updateHeight = useCallback(() => {
      if (trackRef.current) {
        setTrackHeight(trackRef.current.clientHeight)
      }
    }, [])

    useEffect(() => {
      updateHeight()
      window.addEventListener('resize', updateHeight)
      return () => window.removeEventListener('resize', updateHeight)
    }, [updateHeight])

    useEffect(() => {
      if (trackHeight <= 0 || filteredSections.length === 0) return
      progressY.set((activeTick / lastTick) * trackHeight)
    }, [activeTick, lastTick, trackHeight, filteredSections.length, progressY])

    const handleClick = (index: number) => {
      playClickSound()
      if (onIndexChange) {
        onIndexChange(index)
      } else {
        setInternalIndex(index)
      }

      const container = externalScrollRef?.current
      const sectionEl = container?.querySelector(`[data-section-index="${index}"]`)
      if (container && sectionEl) {
        const top =
          sectionEl.getBoundingClientRect().top -
          container.getBoundingClientRect().top +
          container.scrollTop -
          scrollOffset
        container.scrollTo({ top: Math.max(0, top), behavior: reduceMotion ? 'auto' : 'smooth' })
      }
    }

    return (
      <div ref={ref} className={cn('h-full', className)}>
        <div
          ref={trackRef}
          className="h-full relative"
          onMouseEnter={() => setIsHovered(true)}
          onMouseLeave={() => setIsHovered(false)}
        >
          <div className="absolute inset-0">
            {Array.from({ length: totalTicks }).map((_, i) => {
              const y = tickY(i)
              const isMajor = i % 5 === 0
              const isPast = i <= activeTick

              return (
                <div
                  key={i}
                  className="absolute inset-e-0 flex items-center"
                  style={{ top: `${y}px` }}
                >
                  <div
                    className={cn(
                      'h-px transition-colors duration-(--motion-dur-fast) ease motion-reduce:transition-none',
                      isMajor ? 'w-3' : 'w-1.5',
                      isPast
                        ? 'bg-(--color-fg)'
                        : isMajor
                          ? 'bg-(--color-fg)/50'
                          : 'bg-(--color-fg)/25',
                    )}
                  />
                </div>
              )
            })}

            {filteredSections.map((section, i) => {
              const y = tickY(sectionTick(i))
              const isActive = i === activeIndex

              return (
                <div key={section.id}>
                  <div
                    className={cn(
                      'absolute inset-e-0 h-px transition-colors duration-(--motion-dur-fast) ease motion-reduce:transition-none',
                      section.level === 2 ? 'w-4' : 'w-3',
                      isActive ? 'bg-(--color-accent)' : 'bg-(--color-fg)/60',
                    )}
                    style={{ top: `${y}px` }}
                  />

                  <div
                    className={cn(
                      'absolute flex items-center',
                      reduceMotion
                        ? ''
                        : 'transition-[opacity,translate] duration-(--motion-dur-base) ease-(--motion-ease-out)',
                      isHovered ? 'opacity-100 translate-x-0' : 'opacity-0 translate-x-2',
                    )}
                    style={{
                      top: `${y - 7}px`,
                      insetInlineEnd: '20px',
                      transitionDelay: isHovered ? `${i * 35}ms` : '0ms',
                    }}
                  >
                    <button
                      type="button"
                      onMouseEnter={() => playHoverSound()}
                      onClick={() => handleClick(i)}
                      className={cn(
                        'font-mono text-[11px] uppercase tracking-wider cursor-pointer bg-transparent border-0 p-0 whitespace-nowrap rounded-md',
                        'transition-colors duration-(--motion-dur-fast) ease motion-reduce:transition-none',
                        'focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-(--color-accent) focus-visible:ring-offset-1 focus-visible:ring-offset-(--color-bg)',
                        isActive
                          ? 'text-(--color-accent)'
                          : 'text-(--color-muted) hover:text-(--color-fg)',
                      )}
                    >
                      {section.title}
                    </button>
                  </div>
                </div>
              )
            })}

            <motion.div className="absolute top-0 inset-e-0 z-20" style={{ y: smoothY }}>
              <div className="h-px w-4 bg-(--color-accent)" />
              <div
                className={cn(
                  'absolute top-0 -inset-s-8 -translate-y-1/2 transition-opacity duration-(--motion-dur-fast) ease motion-reduce:transition-none',
                  isHovered ? 'opacity-0' : 'opacity-100',
                )}
              >
                <span className="font-mono text-[10px] text-(--color-accent) tabular-nums">
                  {filteredSections.length > 0
                    ? `${activeIndex + 1}/${filteredSections.length}`
                    : '0/0'}
                </span>
              </div>
            </motion.div>
          </div>
        </div>
      </div>
    )
  },
)

'use client'

const MUTE_KEY = 'sound-muted'
const MUTE_EVENT = 'sound-mute-change'

let muted = false
if (typeof window !== 'undefined') {
  try {
    muted = localStorage.getItem(MUTE_KEY) === '1'
  } catch {}
}

export function isSoundMuted(): boolean {
  return muted
}

export function setSoundMuted(value: boolean) {
  muted = value
  if (typeof window !== 'undefined') {
    try {
      localStorage.setItem(MUTE_KEY, value ? '1' : '0')
    } catch {}
    window.dispatchEvent(new CustomEvent(MUTE_EVENT))
  }
}

export function toggleSoundMuted(): boolean {
  setSoundMuted(!muted)
  return muted
}

export function subscribeSoundMuted(callback: () => void) {
  if (typeof window === 'undefined') return () => {}
  window.addEventListener(MUTE_EVENT, callback)
  const onStorage = (e: StorageEvent) => {
    if (e.key === MUTE_KEY) callback()
  }
  window.addEventListener('storage', onStorage)
  return () => {
    window.removeEventListener(MUTE_EVENT, callback)
    window.removeEventListener('storage', onStorage)
  }
}

let audioCtx: AudioContext | null = null

function initAudio(): AudioContext | null {
  if (typeof window === 'undefined') return null
  if (!audioCtx) {
    const AudioContextClass =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext
    if (AudioContextClass) {
      audioCtx = new AudioContextClass()
    }
  }
  if (audioCtx && audioCtx.state === 'suspended') {
    audioCtx.resume().catch(() => {})
  }
  return audioCtx
}

if (typeof window !== 'undefined') {
  const unlock = () => {
    initAudio()
    window.removeEventListener('pointerdown', unlock)
    window.removeEventListener('keydown', unlock)
    window.removeEventListener('touchstart', unlock)
  }
  window.addEventListener('pointerdown', unlock, { passive: true })
  window.addEventListener('keydown', unlock, { passive: true })
  window.addEventListener('touchstart', unlock, { passive: true })
}

export function getAudioContext(): AudioContext | null {
  return initAudio()
}

export function playHoverSound(volume = 0.12, pitch = 1.2) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(1400 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(350 * pitch, now + 0.012)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.012)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.012)
  } catch {}
}

export function playClickSound(volume = 0.2, pitch = 1.0) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'triangle'
    osc.frequency.setValueAtTime(850 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(160 * pitch, now + 0.02)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.02)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.02)
  } catch {}
}

export function playTickSound(volume = 0.1, pitch = 1.5) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(1800 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(450 * pitch, now + 0.01)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.01)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.01)
  } catch {}
}

export function playTileNote(frequency = 440, volume = 0.08) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime
    const dur = 1.1

    const osc = ctx.createOscillator()
    const shimmer = ctx.createOscillator()
    const shimmerGain = ctx.createGain()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(frequency, now)
    shimmer.type = 'sine'
    shimmer.frequency.setValueAtTime(frequency * 2, now)

    shimmerGain.gain.setValueAtTime(0.22, now)
    shimmerGain.gain.exponentialRampToValueAtTime(0.0001, now + dur * 0.5)

    gain.gain.setValueAtTime(0.0001, now)
    gain.gain.exponentialRampToValueAtTime(volume, now + 0.015)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + dur)

    shimmer.connect(shimmerGain)
    shimmerGain.connect(gain)
    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + dur)
    shimmer.start(now)
    shimmer.stop(now + dur)
  } catch {}
}

export function playBounceSound(volume = 0.3, pitch = 1.0) {
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(260 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(650 * pitch, now + 0.04)
    osc.frequency.exponentialRampToValueAtTime(190 * pitch, now + 0.14)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.14)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.14)

    const subOsc = ctx.createOscillator()
    const subGain = ctx.createGain()

    subOsc.type = 'triangle'
    subOsc.frequency.setValueAtTime(420 * pitch, now)
    subOsc.frequency.exponentialRampToValueAtTime(120 * pitch, now + 0.05)

    subGain.gain.setValueAtTime(volume * 0.7, now)
    subGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.05)

    subOsc.connect(subGain)
    subGain.connect(ctx.destination)

    subOsc.start(now)
    subOsc.stop(now + 0.05)
  } catch {}
}
